tool_input.command:
python3 -I - <<'EOF'
p='SubmissionDescription.ts'
s=open(p).read()
s=s.replace("""				action: 'Update the validation status for a submission',
			},
""","""				action: 'Update the validation status for a submission',
			},
			{
				name: 'Update Validation Status (Many)',
				value: 'setValidationMany',
				description: 'Set the validation status of many submissions',
				action: 'Update the validation status for many submissions',
			},
""")
s=s.replace("operation: ['get', 'delete', 'getValidation', 'setValidation', 'getAll'],","operation: [\n\t\t\t\t\t'get',\n\t\t\t\t\t'delete',\n\t\t\t\t\t'getValidation',\n\t\t\t\t\t'setValidation',\n\t\t\t\t\t'setValidationMany',\n\t\t\t\t\t'getAll',\n\t\t\t\t],")
s=s.replace("""	{
		displayName: 'Validation Status',
		name: 'validationStatus',
		type: 'options',
		required: true,
		displayOptions: {
			show: {
				resource: ['submission'],
				operation: ['setValidation'],""","""	{
		displayName: 'Submission IDs',
		name: 'submissionIds',
		type: 'string',
		required: true,
		default: '',
		placeholder: 'e.g. 245128, 245129',
		displayOptions: {
			show: {
				resource: ['submission'],
				operation: ['setValidationMany'],
			},
		},
		description: 'Comma-separated list of submission IDs (numbers)',
	},
	{
		displayName: 'Validation Status',
		name: 'validationStatus',
		type: 'options',
		required: true,
		displayOptions: {
			show: {
				resource: ['submission'],
				operation: ['setValidation', 'setValidationMany'],""")
open(p,'w').write(s)

p='KoBoToolbox.node.ts'
s=open(p).read()
s=s.replace("import { NodeConnectionTypes } from","import { NodeConnectionTypes, NodeOperationError } from")
anchor="""			if (resource === 'hook') {
				const formId"""
new="""				if (operation === 'setValidationMany') {
					// ----------------------------------
					//          Submissions: setValidationMany
					// ----------------------------------
					const rawIds = this.getNodeParameter('submissionIds', i) as string;
					const status = this.getNodeParameter('validationStatus', i) as string;
					const ids = parseStringList(rawIds);

					if (ids.length === 0) {
						throw new NodeOperationError(this.getNode(), 'The submission ID list is empty', {
							itemIndex: i,
							description: 'Enter one or more submission IDs, separated by commas',
						});
					}

					const invalidId = ids.find((id) => !/^\\d+$/.test(id));
					if (invalidId !== undefined) {
						throw new NodeOperationError(
							this.getNode(),
							`The submission ID "${invalidId}" is not a number`,
							{ itemIndex: i },
						);
					}

					// One request for each ID, so that the result of each submission is known
					responseData = [];
					for (const id of ids) {
						try {
							await koBoToolboxApiRequest.call(this, {
								method: 'PATCH',
								url: `/api/v2/assets/${formId}/data/${id}/validation_status/`,
								body: {
									'validation_status.uid': status,
								},
							});
							responseData.push({ submissionId: id, updated: true });
						} catch (error) {
							responseData.push({
								submissionId: id,
								updated: false,
								error: (error as Error).message,
							});
						}
					}
				}
			}

"""
i=s.index(anchor)
# remove the closing brace of submission block preceding anchor
head=s[:i].rstrip()
assert head.endswith('}')
head=head[:-1].rstrip()+"\n\n"
s=head+new+s[i:]
open(p,'w').write(s)
EOF
git diff --stat; grep -n "parseStringList" -A12 GenericFunctions.ts | head -20
